UPDATE artifact_asset
SET tenant_id = #{tenantId}, owner_user_id = #{ownerUserId}, visibility = #{visibility}, session_id = #{sessionId}, message_id = #{messageId}, asset_id = #{assetId}, asset_kind = #{assetKind}, asset_type = #{assetType}, bucket = #{bucket}, object_key = #{objectKey}, file_name = #{fileName}, mime_type = #{mimeType}, size_bytes = #{sizeBytes}, sha256 = #{sha256}, status = #{status}, parse_status = #{parseStatus}, extracted_text = #{extractedText}, parse_error = #{parseError}, metadata = #{metadata}
WHERE id = #{id} AND deleted = 0

mapper.select:
SELECT 
FROM artifact_asset
WHERE owner_user_id = #{ownerUserId} AND status = 'active' AND deleted = 0
  AND ((#{tenantId} IS NULL AND tenant_id IS NULL) OR tenant_id = #{tenantId})
  AND id < #{cursor}
  AND session_id = #{sessionId}
  AND asset_kind = #{assetKind}
ORDER BY id DESC LIMIT #{limit}

SELECT COUNT(*)
FROM artifact_asset a
INNER JOIN chat_message m ON m.message_id = a.message_id
  AND m.tenant_id <=> a.tenant_id AND m.user_id = a.owner_user_id AND m.session_id = a.session_id
WHERE a.owner_user_id = #{ownerUserId} AND a.session_id = #{sessionId}
  AND ((#{tenantId} IS NULL AND a.tenant_id IS NULL) OR a.tenant_id = #{tenantId})
  AND a.status = 'active' AND a.parse_status = 'ready' AND a.deleted = 0
  AND m.validity_status = 'active' AND m.role = 'user' AND m.deleted = 0
  AND m.sequence_no > #{fromSequenceExclusive}
  AND m.sequence_no <= #{visibleThroughSequence}
